package com.hanyuflow.android;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.util.UUID;
import org.json.*;

/** Local guided/repeat runs. Scores describe this small syllabus, never pronunciation or fluency. */
final class ProgramStore {
 interface Clock {long now();}
 private final SQLiteDatabase db;private final JSONObject program,curriculum;private final Clock clock;
 ProgramStore(SQLiteDatabase db,JSONObject program,JSONObject curriculum,Clock clock){this.db=db;this.program=program;this.curriculum=curriculum;this.clock=clock;}
 static void createTables(SQLiteDatabase db){
  db.execSQL("CREATE TABLE IF NOT EXISTS program_runs (id TEXT PRIMARY KEY,course_id TEXT NOT NULL,version TEXT NOT NULL,kind TEXT NOT NULL,novel INTEGER NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'ACTIVE',started_at INTEGER NOT NULL,completed_at INTEGER,accuracy INTEGER,unhinted_accuracy INTEGER)");
  db.execSQL("CREATE TABLE IF NOT EXISTS program_attempts (event_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,exercise_order INTEGER NOT NULL,attempt_no INTEGER NOT NULL,answer TEXT NOT NULL,correct INTEGER NOT NULL,hint_used INTEGER NOT NULL,created_at INTEGER NOT NULL,UNIQUE(run_id,exercise_order,attempt_no))");
  db.execSQL("CREATE TABLE IF NOT EXISTS program_help (run_id TEXT NOT NULL,exercise_order INTEGER NOT NULL,kind TEXT NOT NULL,PRIMARY KEY(run_id,exercise_order,kind))");
  db.execSQL("CREATE TABLE IF NOT EXISTS program_mistakes (item_key TEXT PRIMARY KEY,course_id TEXT NOT NULL,exercise_order INTEGER NOT NULL,due INTEGER NOT NULL,repetitions INTEGER NOT NULL DEFAULT 0,last_correct INTEGER NOT NULL DEFAULT 0,last_practiced INTEGER)");
  db.execSQL("CREATE TABLE IF NOT EXISTS program_practice (event_id TEXT PRIMARY KEY,item_key TEXT NOT NULL,answer TEXT NOT NULL,correct INTEGER NOT NULL,created_at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE IF NOT EXISTS speaking_practice (id TEXT PRIMARY KEY,phrase TEXT NOT NULL,duration_ms INTEGER NOT NULL,created_at INTEGER NOT NULL,self_check TEXT)");
  db.execSQL("CREATE INDEX IF NOT EXISTS program_course ON program_runs(course_id,started_at)");
 }
 static void migrateLegacyMistakes(SQLiteDatabase db){db.execSQL("INSERT OR IGNORE INTO program_mistakes(item_key,course_id,exercise_order,due) SELECT lesson_id||':'||exercise_order,lesson_id,exercise_order,MIN(created_at) FROM attempts WHERE correct=0 GROUP BY lesson_id,exercise_order");}
 private JSONArray rows(String sql,String...args)throws Exception{JSONArray out=new JSONArray();try(Cursor c=db.rawQuery(sql,args)){while(c.moveToNext()){JSONObject r=new JSONObject();for(int i=0;i<c.getColumnCount();i++)r.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));out.put(r);}}return out;}
 private JSONObject run(String id)throws Exception{JSONArray r=rows("SELECT * FROM program_runs WHERE id=?",id);if(r.length()==0)throw new IllegalArgumentException("Run not found");return r.getJSONObject(0);}
 private JSONObject course(String id)throws Exception{
  for(String group:new String[]{"courses","checkForms"}){JSONArray all=program.getJSONArray(group);for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).getString("id")))return all.getJSONObject(i);}
  JSONArray all=curriculum.getJSONArray("lessons");for(int i=0;i<all.length();i++){JSONObject old=all.getJSONObject(i);if(!id.equals(old.getString("id")))continue;JSONObject result=new JSONObject(old.toString()).put("section","legacy").put("notes",new JSONArray()).put("dialogues",new JSONArray()).put("speakText","");JSONArray tasks=result.getJSONArray("exercises");for(int j=0;j<tasks.length();j++){JSONObject e=tasks.getJSONObject(j);String type=e.getString("type");e.put("id",id+":"+j).put("skill",type.equals("ordering")||type.equals("blank")||type.equals("dialogue")?"application":"recognition");if(type.equals("blank"))e.put("type","recall");if(!e.isNull("hanzi")){e.put("text",e.getString("hanzi"));if(!type.equals("dialogue"))e.put("audioText",e.getString("hanzi"));}JSONObject labels=new JSONObject();JSONArray words=curriculum.getJSONArray("words");for(int k=0;k<words.length();k++)labels.put(words.getJSONObject(k).getString("id"),words.getJSONObject(k).getJSONObject("translation"));e.put("labels",labels);}return result;}
  throw new IllegalArgumentException("Module not found");
 }
 private String kind(JSONObject c)throws Exception{return c.getString("section").equals("check")?"CHECK":c.getString("section").equals("legacy")?"REPEAT":"GUIDED";}
 private int completedCourses()throws Exception{return rows("SELECT DISTINCT course_id FROM program_runs WHERE kind='GUIDED' AND status='DONE' AND version=?",program.getString("version")).length();}
 private JSONArray passes()throws Exception{return rows("SELECT * FROM program_runs WHERE kind='CHECK' AND novel=1 AND status='DONE' AND unhinted_accuracy>=80 AND version=? ORDER BY completed_at",program.getString("version"));}
 JSONObject start(String courseId,boolean restart,String timezone)throws Exception{
  JSONObject c=course(courseId);String kind=kind(c);long now=clock.now();
  if(kind.equals("REPEAT")){JSONArray p=rows("SELECT completed_at FROM progress WHERE lesson_id=?",courseId);if(p.length()==0||p.getJSONObject(0).isNull("completed_at"))throw new IllegalArgumentException("Finish the original lesson once before repeat practice.");}
  if(kind.equals("CHECK")&&completedCourses()<program.getJSONArray("courses").length())throw new IllegalArgumentException("Complete the10 guided modules before a mixed check.");
  JSONArray existing=rows("SELECT * FROM program_runs WHERE course_id=? AND version=? ORDER BY started_at DESC",courseId,program.getString("version"));
  if(!restart&&existing.length()>0&&existing.getJSONObject(0).getString("status").equals("ACTIVE"))return payload(existing.getJSONObject(0),c);
  boolean novel=existing.length()==0;JSONArray passed=passes();
  if(kind.equals("CHECK")&&novel&&passed.length()>0){long first=passed.getJSONObject(0).getLong("completed_at");if(!retentionReady(first,now,timezone))throw new IllegalArgumentException("A fresh follow-up check opens at least24hours later and on a later study day. Repeat the used form for practice meanwhile.");}
  if(existing.length()>0&&existing.getJSONObject(0).getString("status").equals("ACTIVE"))db.execSQL("UPDATE program_runs SET status='ABANDONED' WHERE id=?",new Object[]{existing.getJSONObject(0).getString("id")});
  String id=UUID.randomUUID().toString();db.execSQL("INSERT INTO program_runs(id,course_id,version,kind,novel,started_at) VALUES (?,?,?,?,?,?)",new Object[]{id,courseId,program.getString("version"),kind,novel?1:0,now});return payload(run(id),c);
 }
 static boolean retentionReady(long first,long now,String timezone){return now-first>=86400000L&&!LearningRules.day(first,timezone).equals(LearningRules.day(now,timezone));}
 // A delayed Finish tap is not delayed retrieval. A pre-opened form remains resumable
 // practice, but cannot be follow-up evidence for a pass completed after it was opened.
 static boolean retentionEvidenceReady(long firstCompleted,long followupStarted,long followupCompleted,String timezone){return followupCompleted>=followupStarted&&retentionReady(firstCompleted,followupStarted,timezone);}
 private JSONObject payload(JSONObject run,JSONObject c)throws Exception{return new JSONObject().put("run",run).put("course",c).put("attempts",rows("SELECT * FROM program_attempts WHERE run_id=? ORDER BY exercise_order,attempt_no",run.getString("id")));}
 JSONObject help(JSONObject input)throws Exception{JSONObject r=run(input.getString("runId"));int order=input.getInt("order");JSONObject c=course(r.getString("course_id"));if(!r.getString("status").equals("ACTIVE")||order<0||order>=c.getJSONArray("exercises").length())throw new IllegalArgumentException("Invalid help request");db.execSQL("INSERT OR IGNORE INTO program_help VALUES (?,?,?)",new Object[]{r.getString("id"),order,input.optString("kind","HINT")});return new JSONObject().put("assisted",true);}
 private JSONObject feedback(JSONObject e,boolean correct,boolean assisted)throws Exception{return new JSONObject().put("correct",correct).put("assisted",assisted).put("answer",e.get("answer")).put("explanation",e.getJSONObject("explanation"));}
 JSONObject attempt(JSONObject input)throws Exception{
  String event=input.getString("eventId"),id=input.getString("runId");UUID.fromString(event);int order=input.getInt("order");Object answer=input.get("answer");String encoded=new JSONObject().put("answer",answer).toString();if(encoded.length()>10000)throw new IllegalArgumentException("Answer too large");
  JSONObject r=run(id),c=course(r.getString("course_id"));JSONArray tasks=c.getJSONArray("exercises");if(order<0||order>=tasks.length())throw new IllegalArgumentException("Task not found");JSONObject e=tasks.getJSONObject(order);
  db.beginTransaction();try{
   JSONArray prior=rows("SELECT * FROM program_attempts WHERE event_id=?",event);if(prior.length()>0){JSONObject p=prior.getJSONObject(0);if(!p.getString("run_id").equals(id)||p.getInt("exercise_order")!=order||!p.getString("answer").equals(encoded))throw new IllegalArgumentException("Attempt identity conflict");db.setTransactionSuccessful();return feedback(e,p.getInt("correct")==1,p.getInt("hint_used")==1);}
   if(!r.getString("status").equals("ACTIVE")||order>r.getInt("cursor"))throw new IllegalArgumentException("Answer the active run in order");
   int n=rows("SELECT event_id FROM program_attempts WHERE run_id=? AND exercise_order=?",id,String.valueOf(order)).length();if(n>=20)throw new IllegalArgumentException("Try a fresh practice run after20 attempts");
   boolean assisted=rows("SELECT kind FROM program_help WHERE run_id=? AND exercise_order=?",id,String.valueOf(order)).length()>0;
   boolean correct=LearningRules.grade(e.getString("type"),answer,e.get("answer"),e.optJSONArray("alternatives")==null?new JSONArray():e.getJSONArray("alternatives"));long now=clock.now();
   db.execSQL("INSERT INTO program_attempts VALUES (?,?,?,?,?,?,?,?)",new Object[]{event,id,order,n+1,encoded,correct?1:0,assisted?1:0,now});db.execSQL("UPDATE program_runs SET cursor=MAX(cursor,?) WHERE id=?",new Object[]{order+1,id});
   if(!correct&&!r.getString("kind").equals("CHECK"))db.execSQL("INSERT OR IGNORE INTO program_mistakes(item_key,course_id,exercise_order,due) VALUES (?,?,?,?)",new Object[]{r.getString("course_id")+":"+order,r.getString("course_id"),order,now});
   db.setTransactionSuccessful();return feedback(e,correct,assisted);
  }finally{db.endTransaction();}
 }
 JSONObject complete(String id)throws Exception{
  JSONObject r=run(id),c=course(r.getString("course_id"));if(r.getString("status").equals("DONE"))return new JSONObject().put("accuracy",r.getInt("accuracy")).put("unhintedAccuracy",r.getInt("unhinted_accuracy")).put("duplicate",true).put("points",0).put("novel",r.getInt("novel")==1);
  if(!r.getString("status").equals("ACTIVE"))throw new IllegalArgumentException("Run is not active");
  int first=0,unhinted=0,latest=0;JSONArray tasks=c.getJSONArray("exercises");
  for(int i=0;i<tasks.length();i++){JSONArray a=rows("SELECT correct,hint_used FROM program_attempts WHERE run_id=? AND exercise_order=? ORDER BY attempt_no",id,String.valueOf(i));if(a.length()==0)throw new IllegalArgumentException("Answer every task");if(a.getJSONObject(0).getInt("correct")==1){first++;if(a.getJSONObject(0).getInt("hint_used")==0)unhinted++;}if(a.getJSONObject(a.length()-1).getInt("correct")==1)latest++;}
  if(!r.getString("kind").equals("CHECK")&&latest*100/tasks.length()<80)throw new IllegalArgumentException("Practice the remaining mistakes before completing this guided module");
  int score=Math.round(first*100f/tasks.length()),fresh=Math.round(unhinted*100f/tasks.length()),points=0;long now=clock.now();db.beginTransaction();try{
   db.execSQL("UPDATE program_runs SET status='DONE',completed_at=?,accuracy=?,unhinted_accuracy=? WHERE id=?",new Object[]{now,score,fresh,id});
   if(r.getString("kind").equals("GUIDED")){String ledger="program:"+r.getString("course_id");if(rows("SELECT event_id FROM practice_points WHERE event_id=?",ledger).length()==0){points=20+Math.round(score/5f);db.execSQL("INSERT INTO practice_points VALUES (?,?,?,?)",new Object[]{ledger,points,"PROGRAM",now});}}
   if(r.getString("kind").equals("GUIDED")){JSONArray vocab=c.getJSONArray("vocabulary");for(int i=0;i<vocab.length();i++)db.execSQL("INSERT OR IGNORE INTO reviews(vocab_id,due) VALUES (?,?)",new Object[]{vocab.getString(i),now});}
   db.setTransactionSuccessful();
  }finally{db.endTransaction();}
  return new JSONObject().put("accuracy",score).put("unhintedAccuracy",fresh).put("points",points).put("duplicate",false).put("novel",r.getInt("novel")==1).put("passed",fresh>=80).put("isCheck",r.getString("kind").equals("CHECK"));
 }
 JSONObject mistakes()throws Exception{JSONArray all=rows("SELECT * FROM program_mistakes ORDER BY due");JSONArray items=new JSONArray();for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);try{JSONObject c=course(row.getString("course_id"));row.put("task",c.getJSONArray("exercises").getJSONObject(row.getInt("exercise_order"))).put("title",c.getJSONObject("title"));items.put(row);}catch(JSONException ignored){}}return new JSONObject().put("now",clock.now()).put("items",items);}
 JSONObject practice(JSONObject input)throws Exception{
  String key=input.getString("key"),event=input.getString("eventId");UUID.fromString(event);String answer=new JSONObject().put("answer",input.get("answer")).toString();JSONArray row=rows("SELECT * FROM program_mistakes WHERE item_key=?",key);if(row.length()==0)throw new IllegalArgumentException("Mistake not found");JSONObject item=row.getJSONObject(0),e=course(item.getString("course_id")).getJSONArray("exercises").getJSONObject(item.getInt("exercise_order"));JSONArray existing=rows("SELECT * FROM program_practice WHERE event_id=?",event);if(existing.length()>0){JSONObject p=existing.getJSONObject(0);if(!p.getString("item_key").equals(key)||!p.getString("answer").equals(answer))throw new IllegalArgumentException("Practice identity conflict");return feedback(e,p.getInt("correct")==1,false).put("duplicate",true);}
  long now=clock.now();if(item.getLong("due")>now)throw new IllegalArgumentException("This practice item is not due yet");boolean correct=LearningRules.grade(e.getString("type"),input.get("answer"),e.get("answer"),e.optJSONArray("alternatives")==null?new JSONArray():e.getJSONArray("alternatives"));
  db.beginTransaction();try{db.execSQL("INSERT INTO program_practice VALUES (?,?,?,?,?)",new Object[]{event,key,answer,correct?1:0,now});db.execSQL("UPDATE program_mistakes SET due=?,repetitions=?,last_correct=?,last_practiced=? WHERE item_key=?",new Object[]{now+(correct?86400000L:600000L),correct?item.getInt("repetitions")+1:0,correct?1:0,now,key});db.setTransactionSuccessful();}finally{db.endTransaction();}return feedback(e,correct,false).put("points",0).put("duplicate",false);
 }
 boolean validSpeakingPhrase(String phrase)throws Exception{JSONArray courses=program.getJSONArray("courses");for(int i=0;i<courses.length();i++){JSONObject c=courses.getJSONObject(i);if(phrase.equals(c.optString("speakText")))return true;JSONArray d=c.getJSONArray("dialogues");for(int j=0;j<d.length();j++)for(int k=0;k<d.getJSONArray(j).length();k++)if(phrase.equals(d.getJSONArray(j).getJSONObject(k).getString("text")))return true;}return phrase.equals("你好！我叫安娜。");}
 JSONObject recordSpeaking(String phrase,long ms)throws Exception{if(!validSpeakingPhrase(phrase)||ms<500||ms>61000)throw new IllegalArgumentException("Invalid guided recording");String id=UUID.randomUUID().toString();db.execSQL("INSERT INTO speaking_practice(id,phrase,duration_ms,created_at) VALUES (?,?,?,?)",new Object[]{id,phrase,ms,clock.now()});return new JSONObject().put("id",id).put("attempted",true).put("assessed",false);}
 JSONObject selfCheck(String id,String value)throws Exception{if(!java.util.Arrays.asList("NOT_YET","SIMILAR","UNSURE").contains(value))throw new IllegalArgumentException("Invalid self-check");if(rows("SELECT id FROM speaking_practice WHERE id=?",id).length()==0)throw new IllegalArgumentException("Recording attempt not found");db.execSQL("UPDATE speaking_practice SET self_check=? WHERE id=?",new Object[]{value,id});return new JSONObject().put("saved",true).put("assessed",false);}
 JSONObject summary(String timezone)throws Exception{
  JSONArray done=rows("SELECT * FROM program_runs WHERE status='DONE' AND version=? ORDER BY completed_at",program.getString("version"));JSONArray pass=passes();boolean confirmed=false;for(int i=0;i<pass.length();i++)for(int j=i+1;j<pass.length();j++)if(!pass.getJSONObject(i).getString("course_id").equals(pass.getJSONObject(j).getString("course_id"))&&retentionEvidenceReady(pass.getJSONObject(i).getLong("completed_at"),pass.getJSONObject(j).getLong("started_at"),pass.getJSONObject(j).getLong("completed_at"),timezone))confirmed=true;
  JSONObject skills=new JSONObject();for(String s:new String[]{"recognition","listening","application"})skills.put(s,new JSONObject().put("correct",0).put("total",0));java.util.Set<String> counted=new java.util.HashSet<>();
  for(int i=0;i<done.length();i++){JSONObject r=done.getJSONObject(i);if(!r.getString("kind").equals("GUIDED")||!counted.add(r.getString("course_id")))continue;JSONArray tasks=course(r.getString("course_id")).getJSONArray("exercises");for(int k=0;k<tasks.length();k++){JSONObject e=tasks.getJSONObject(k);if(e.optBoolean("provisional"))continue;JSONArray attempts=rows("SELECT correct,hint_used FROM program_attempts WHERE run_id=? AND exercise_order=? AND attempt_no=1",r.getString("id"),String.valueOf(k));if(attempts.length()==0)continue;JSONObject v=skills.getJSONObject(e.getString("skill"));v.put("total",v.getInt("total")+1);if(attempts.getJSONObject(0).getInt("correct")==1&&attempts.getJSONObject(0).getInt("hint_used")==0)v.put("correct",v.getInt("correct")+1);}}
  JSONArray forms=new JSONArray(),raw=rows("SELECT * FROM program_runs WHERE version=? ORDER BY started_at",program.getString("version"));for(int i=0;i<program.getJSONArray("checkForms").length();i++){String id=program.getJSONArray("checkForms").getJSONObject(i).getString("id");boolean seen=rows("SELECT id FROM program_runs WHERE course_id=? AND version=?",id,program.getString("version")).length()>0;forms.put(new JSONObject().put("id",id).put("seen",seen).put("freshAllowed",completedCourses()>=program.getJSONArray("courses").length()&&(seen||pass.length()==0||retentionReady(pass.getJSONObject(0).getLong("completed_at"),clock.now(),timezone))));}
  return new JSONObject().put("version",program.getString("version")).put("runs",raw).put("completedCourses",completedCourses()).put("skills",skills).put("forms",forms).put("masteryConfirmed",confirmed).put("firstFreshPassAt",pass.length()==0?JSONObject.NULL:pass.getJSONObject(0).getLong("completed_at")).put("speakingAttempts",rows("SELECT id,phrase,duration_ms,created_at,self_check FROM speaking_practice ORDER BY created_at DESC")).put("mistakesDue",rows("SELECT item_key FROM program_mistakes WHERE due<=?",String.valueOf(clock.now())).length()).put("pronunciationAssessed",false);
 }
 JSONObject export()throws Exception{return new JSONObject().put("runs",rows("SELECT * FROM program_runs")).put("attempts",rows("SELECT * FROM program_attempts")).put("help",rows("SELECT * FROM program_help")).put("mistakes",rows("SELECT * FROM program_mistakes")).put("practice",rows("SELECT * FROM program_practice")).put("speaking",rows("SELECT * FROM speaking_practice"));}
 static void clear(SQLiteDatabase db){for(String t:new String[]{"program_runs","program_attempts","program_help","program_mistakes","program_practice","speaking_practice"})db.delete(t,null,null);}
}
